PageHandlerAsyncWaiter::PageHandlerAsyncWaiter(
    PageHandler* proxy) : proxy_(proxy) {}

PageHandlerAsyncWaiter::~PageHandlerAsyncWaiter() = default;


void PageHandlerAsyncWaiter::GetTriggeringPageInfo(
    std::string* out_pageUrl, ::GURL* out_screenshotDataUri) {
  base::RunLoop loop;
  proxy_->GetTriggeringPageInfo(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_pageUrl
,
             ::GURL* out_screenshotDataUri
,
             const std::string& pageUrl,
             const ::GURL& screenshotDataUri) {*out_pageUrl = std::move(pageUrl);*out_screenshotDataUri = std::move(screenshotDataUri);
            loop->Quit();
          },
          &loop,
          out_pageUrl,
          out_screenshotDataUri));
  loop.Run();
}



void PageHandlerAsyncWaiter::SendReport(
    bool includeScreenshot) {
  base::RunLoop loop;
  proxy_->SendReport(
      std::move(includeScreenshot),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}






